# domain.py
def can_complete(lesson_id, known_lessons):
    return lesson_id in known_lessons

# service.py
def import_completion(row, known_lessons, repository):
    lesson_id = row.get('lesson_id')
    if not can_complete(lesson_id, known_lessons):
        return {'ok': False, 'error': 'unknown lesson'}
    repository.save_completion(lesson_id)
    return {'ok': True}

# repository is an adapter: it may save to memory, a file, or a database.

lab.solution:
def import_decision(lesson_id, known_ids, completed):
    if lesson_id not in known_ids:
        return {'ok': False, 'error_code': 'unknown_lesson'}
    already_done = lesson_id in completed
    completed.add(lesson_id)
    return {'ok': True, 'already_done': already_done}

completed = set()
assert import_decision('loops', {'loops'}, completed) == {'ok': True, 'already_done': False}
assert import_decision('loops', {'loops'}, completed) == {'ok': True, 'already_done': True}

